from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode


def apply_rewrite_rules(rules, urls):
    results = []

    for url in urls:
        parsed = urlparse(url)
        rewritten = False

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            matched = False

            # 1. Check matching
            if match_type == "path_prefix":
                if parsed.path.startswith(match_value):
                    matched = True

            elif match_type == "host":
                host = parsed.hostname or ""
                if match_value.startswith("*."):
                    suffix = match_value[1:]  # e.g., ".example.com"
                    # Must be a strict subdomain
                    if host.endswith(suffix) and len(host) > len(suffix):
                        matched = True
                else:
                    if host == match_value:
                        matched = True

            elif match_type == "query_param":
                query_params = parse_qsl(parsed.query, keep_blank_values=True)
                if any(k == match_value for k, v in query_params):
                    matched = True

            # 2. If matched, apply action and stop evaluating further rules for this URL
            if matched:
                if action == "block":
                    results.append(None)
                    rewritten = True
                    break

                elif action == "strip_prefix":
                    # Remove action_value from the start of the path
                    if parsed.path.startswith(action_value):
                        new_path = parsed.path[len(action_value) :]
                        if not new_path:
                            new_path = "/"
                    else:
                        new_path = parsed.path

                    parsed = parsed._replace(path=new_path)
                    results.append(urlunparse(parsed))
                    rewritten = True
                    break

                elif action == "redirect_host":
                    # Replace the host, preserving port if it was part of netloc
                    netloc = action_value
                    if parsed.port:
                        netloc = f"{action_value}:{parsed.port}"

                    parsed = parsed._replace(netloc=netloc)
                    results.append(urlunparse(parsed))
                    rewritten = True
                    break

                elif action == "add_query_param":
                    # action_value is expected to be like "key=value"
                    if "=" in action_value:
                        k, v = action_value.split("=", 1)
                    else:
                        k, v = action_value, ""

                    query_params = parse_qsl(parsed.query, keep_blank_values=True)
                    query_params.append((k, v))
                    new_query = urlencode(query_params)

                    parsed = parsed._replace(query=new_query)
                    results.append(urlunparse(parsed))
                    rewritten = True
                    break

        if not rewritten:
            results.append(url)

    return results
